// AF-ON profile codec. Pure. The storage key is not named here.
// Packs the T6 fields into 26 bytes: marker, version, the fields, CRC-16, spare zeros.
// A failed marker, version, checksum, spare, padding, or range check decodes as null
// ("no profile"). Do not edit this file after it has run.

export const RECORD_BYTES = 26;
export const MARKER = 0xa70f;
export const VERSION = 1;
export const POSITION_MAX = 1052;

// Descriptor order, measured from the image. The stored code is the index.
export const ZONE = [0, 1, 2, 3, 5, 10, 6, 7, 8, 9];
export const DIM_V = [1, 3, 5, 7, 9, 11, 15, 19, 23, 27];
export const DIM_H = [1, 3, 5, 7, 9, 11, 15, 19, 23, 27, 33, 39];
export const STEP_V = [1, 2, 3, 4, 5];
export const STEP_H = [1, 2, 3, 4, 5, 6, 7, 8];

export const BANKS = [1, 5, 3];
export const MIRROR_BYTES = 71;

// Bits before the checksum, then 3 pad bits, then 16 checksum bits. 20 bytes used.
export const FIELD_BITS = 141;
export const PAD_BITS = 3;
export const CRC_BITS = 16;
export const USED_BYTES = 20;

const DIM_V_INDEX = [0, 2, 4, 6, 8];
const DIM_H_INDEX = [1, 3, 5, 7, 9];
const STEP_V_INDEX = [0, 2, 4, 6];
const STEP_H_INDEX = [1, 3, 5, 7];

function u8(n, name) {
  if (!Number.isInteger(n) || n < 0 || n > 255) throw new RangeError(name);
  return n;
}

function codeOf(table, value, width, name) {
  if (!Number.isInteger(value)) throw new RangeError(name);
  const code = table.indexOf(value);
  if (code < 0 || code >= (1 << width)) throw new RangeError(name);
  return code;
}

function valueOf(table, code, width) {
  if (!Number.isInteger(code) || code < 0 || code >= (1 << width) || code >= table.length) return null;
  return table[code];
}

function writeBits(buf, pos, value, width) {
  for (let i = 0; i < width; i++) {
    if ((value >>> i) & 1) buf[(pos + i) >> 3] |= 1 << ((pos + i) & 7);
  }
  return pos + width;
}

function readBits(buf, pos, width) {
  let value = 0;
  for (let i = 0; i < width; i++) {
    if (buf[(pos + i) >> 3] & (1 << ((pos + i) & 7))) value |= 1 << i;
  }
  return value;
}

export function crc16(bytes) {
  let crc = 0xffff;
  for (const b of bytes) {
    crc ^= b;
    for (let i = 0; i < 8; i++) crc = (crc & 1) ? ((crc >>> 1) ^ 0xa001) : (crc >>> 1);
  }
  return crc & 0xffff;
}

function pack(profile) {
  const buf = new Uint8Array(RECORD_BYTES);
  let p = 0;
  p = writeBits(buf, p, MARKER, 16);
  p = writeBits(buf, p, VERSION, 8);
  for (const bank of BANKS) p = writeBits(buf, p, codeOf(ZONE, profile.zone[bank], 4, 'zone ' + bank), 4);
  p = writeBits(buf, p, u8(profile.size, 'size'), 8);
  for (const bank of BANKS) {
    const v = profile.position[bank];
    if (!Number.isInteger(v) || v < 0 || v > POSITION_MAX) throw new RangeError('position ' + bank);
    p = writeBits(buf, p, v, 11);
  }
  for (const index of DIM_V_INDEX) p = writeBits(buf, p, codeOf(DIM_V, profile.dim[index], 4, 'dim ' + index), 4);
  for (const index of DIM_H_INDEX) p = writeBits(buf, p, codeOf(DIM_H, profile.dim[index], 4, 'dim ' + index), 4);
  for (const index of STEP_V_INDEX) p = writeBits(buf, p, codeOf(STEP_V, profile.step[index], 3, 'step ' + index), 3);
  for (const index of STEP_H_INDEX) p = writeBits(buf, p, codeOf(STEP_H, profile.step[index], 3, 'step ' + index), 3);
  if (p !== FIELD_BITS) throw new Error('field bits ' + p);
  p += PAD_BITS;
  if (p !== USED_BYTES * 8 - CRC_BITS) throw new Error('pad');
  const crc = crc16(buf.subarray(0, USED_BYTES - 2));
  p = writeBits(buf, p, crc, 16);
  if (p !== USED_BYTES * 8) throw new Error('used');
  return buf;
}

export function encode(profile) {
  if (!profile || !profile.zone || !profile.position || !profile.dim || !profile.step) throw new RangeError('profile');
  if (profile.dim.length !== 10 || profile.step.length !== 8) throw new RangeError('profile');
  return pack(profile);
}

export function decode(bytes) {
  if (!bytes || bytes.length !== RECORD_BYTES) return null;
  const buf = Uint8Array.from(bytes);
  for (let i = USED_BYTES; i < RECORD_BYTES; i++) if (buf[i] !== 0) return null;
  for (let bit = FIELD_BITS; bit < FIELD_BITS + PAD_BITS; bit++) {
    if (buf[bit >> 3] & (1 << (bit & 7))) return null;
  }
  const expect = crc16(buf.subarray(0, USED_BYTES - 2));
  if (readBits(buf, FIELD_BITS + PAD_BITS, 16) !== expect) return null;
  let p = 0;
  if (readBits(buf, p, 16) !== MARKER) return null;
  p += 16;
  if (readBits(buf, p, 8) !== VERSION) return null;
  p += 8;
  const zone = {};
  for (const bank of BANKS) {
    const v = valueOf(ZONE, readBits(buf, p, 4), 4);
    if (v === null) return null;
    zone[bank] = v;
    p += 4;
  }
  const size = readBits(buf, p, 8);
  p += 8;
  const position = {};
  for (const bank of BANKS) {
    const v = readBits(buf, p, 11);
    if (v > POSITION_MAX) return null;
    position[bank] = v;
    p += 11;
  }
  const dim = new Array(10);
  for (const index of DIM_V_INDEX) {
    const v = valueOf(DIM_V, readBits(buf, p, 4), 4);
    if (v === null) return null;
    dim[index] = v;
    p += 4;
  }
  for (const index of DIM_H_INDEX) {
    const v = valueOf(DIM_H, readBits(buf, p, 4), 4);
    if (v === null) return null;
    dim[index] = v;
    p += 4;
  }
  const step = new Array(8);
  for (const index of STEP_V_INDEX) {
    const v = valueOf(STEP_V, readBits(buf, p, 3), 3);
    if (v === null) return null;
    step[index] = v;
    p += 3;
  }
  for (const index of STEP_H_INDEX) {
    const v = valueOf(STEP_H, readBits(buf, p, 3), 3);
    if (v === null) return null;
    step[index] = v;
    p += 3;
  }
  if (p !== FIELD_BITS) return null;
  return { zone, size, position, dim, step };
}

export function mirrorFromProfile(profile) {
  const m = new Uint8Array(MIRROR_BYTES);
  m.fill(0xff);
  m[1] = profile.zone[1];
  m[5] = profile.zone[5];
  m[3] = profile.zone[3];
  m[8] = profile.size & 0xff;
  const put = (bank, value) => {
    const o = 0x0a + bank * 2;
    m[o] = value & 0xff;
    m[o + 1] = (value >> 8) & 0xff;
  };
  put(1, profile.position[1]);
  put(5, profile.position[5]);
  put(3, profile.position[3]);
  for (let i = 0; i < 10; i++) m[0x16 + i] = profile.dim[i] & 0xff;
  for (let i = 0; i < 8; i++) m[0x37 + i] = profile.step[i] & 0xff;
  return m;
}

export function profileFromMirror(bytes) {
  const m = Uint8Array.from(bytes);
  const u16 = (o) => m[o] | (m[o + 1] << 8);
  return {
    zone: { 1: m[1], 5: m[5], 3: m[3] },
    size: m[8],
    position: { 1: u16(0x0c), 5: u16(0x14), 3: u16(0x10) },
    dim: Array.from(m.subarray(0x16, 0x20)),
    step: Array.from(m.subarray(0x37, 0x3f)),
  };
}

export const PROFILE_A = {
  zone: { 1: 2, 5: 6, 3: 1 },
  size: 0,
  position: { 1: 529, 5: 532, 3: 418 },
  dim: [1, 1, 5, 7, 1, 3, 9, 11, 15, 33],
  step: [5, 8, 1, 2, 3, 4, 4, 1],
};
